<?php require 'header.php'; $db=db_load(); $p=find_item($db['patients'],get('id')); if(!$p) redirect('patients.php'); $aps=array_values(array_filter($db['appointments'],fn($a)=>$a['patient_id']===$p['id'])); $paid=array_sum(array_map(fn($a)=>(float)($a['amount']??0),$aps)); ?><div class="admin-top"><h1><?=e($p['name'])?></h1><div class="actions"><a class="btn btn-outline" href="patient-form.php?id=<?=e($p['id'])?>">Edit Patient</a><a class="btn" href="appointment-edit.php?patient_id=<?=e($p['id'])?>">+ Appointment</a></div></div><div class="dash-cards"><div class="dash-card"><span>Patient No</span><strong style="font-size:20px"><?=e($p['number'])?></strong></div><div class="dash-card"><span>Total Paid</span><strong>₹<?=number_format($paid,2)?></strong></div><div class="dash-card"><span>Total Appointments</span><strong><?=count($aps)?></strong></div><div class="dash-card"><span>Mobile</span><strong style="font-size:20px"><?=e($p['mobile'])?></strong></div></div><div class="form-card"><h2>Patient Details</h2><p><b>DOB:</b> <?=e(date_fmt($p['dob']))?> &nbsp; <b>Age:</b> <?=e($p['age'])?> &nbsp; <b>Gender:</b> <?=e($p['gender'])?> &nbsp; <b>Blood:</b> <?=e($p['blood_group'])?></p><p><b>Address:</b> <?=e($p['address'])?>, <?=e($p['city'])?>, <?=e($p['state'])?>, <?=e($p['country'])?></p></div><br><div class="form-card"><h2>Appointment History</h2><div class="table-wrap"><table><tr><th>Appointment No</th><th>Date</th><th>Time</th><th>Status</th><th>Amount</th><th>Medicine</th><th>Instructions</th><th>Next Appointment</th><th>Action</th></tr><?php foreach($aps as $a): ?><tr><td><?=e($a['number'])?></td><td><?=e(date_fmt($a['date']))?></td><td><?=e($a['time'])?></td><td><span class="badge"><?=e($a['status'])?></span></td><td>₹<?=number_format((float)$a['amount'],2)?></td><td><?=e($a['medicine'])?></td><td><?=e($a['instructions'])?></td><td><?=e(date_fmt($a['next_date']))?></td><td><a class="btn btn-sm btn-outline" href="appointment-edit.php?id=<?=e($a['id'])?>">View / Edit</a></td></tr><?php endforeach; ?></table></div></div><?php require 'footer.php'; ?>
